  SheetBody.fill({ order: 6, Component: Periods }),
  PersonRow.fill({ order: 22, Component: PersonPeriodDueTotals }),
];
1:import { useQuery } from '@tanstack/react-query';
2:import { getJson } from '../../api/http';
3:import { countedAt, dueBy, live, type Claim } from '../claims/claims';
4:import { gradeOn, type Person } from '../people/people';
5:import { claimDue, rateOn, sumDue, type Late, type Rate } from '../rates/rates';
6:import type { DatedValue } from '../settings/settings';
7:
8:/** A period on the sheet: a name unique on the sheet and an inclusive from and to date (yyyy-mm-dd). No two
9: *  periods overlap. A closed period keeps the due-total fixed when it was closed (null while open), and each
10: *  person's due-total fixed then, by person id (empty while open). A soft-closed period keeps them fixed the same
11: *  way, while its claims can still be added and changed. A period may cap the OPEN or PENDING claims each person has in
12: *  it (null: no cap); opening one past the cap is refused. */
13:export type Period = { name: string; from: string; to: string; closed: boolean; closedTotal: string | null;
14:  personTotals: Record<string, string>; soft: boolean; cap: number | null };
15:
16:export const periodsKey = (sheetId: string) => ['sheet', sheetId, 'periods'] as const;
17:
18:/** The sheet's periods, earliest first. */
19:export function usePeriods(sheetId: string) {
20:  return useQuery({
21:    queryKey: periodsKey(sheetId),
22:    queryFn: () => getJson<Period[]>(`/api/sheets/${encodeURIComponent(sheetId)}/periods`),
23:  });
24:}
25:
26:/** The period whose dates contain the date (yyyy-mm-dd), or undefined when none does. */
27:export function periodOf(periods: Period[], date: string): Period | undefined {
28:  return periods.find((p) => p.from <= date && date <= p.to);
29:}
30:
31:/** A person's due-total for a period: while it is open, the dues (as shown on their rows now) of the person's claims
32: *  that counted at the end of its last day (see countedAt) whose due-by falls in it; once closed or soft-closed, the figure fixed for them then (0.00 for a person
33: *  added after). */
34:export function personPeriodDueTotal(period: Period, person: Person, claims: Claim[], people: Person[], rates: Rate[],
35:    floor: DatedValue, late: Late): string {
36:  if (period.closed || period.soft) return period.personTotals?.[String(person.id)] ?? '0.00';
37:  return sumDue(
38:    countedAt(claims.filter((c) => c.personId === person.id), people, period.to, late.today)
39:      .filter((c) => periodOf([period], dueBy(c)))
40:      .map((c) => claimDue(c, rateOn(rates, gradeOn(person, c.date), c.date, c.id), floor, late)),
41:  );
42:}
43:
44:/** A period's due-total as shown on its row: the people's due-totals for it (see personPeriodDueTotal) added up. */
45:export function periodDueTotal(period: Period, claims: Claim[], people: Person[], rates: Rate[], floor: DatedValue,
46:    late: Late): string {
47:  return sumDue(people.map((p) => personPeriodDueTotal(period, p, claims, people, rates, floor, late)));
48:}
49:
50:/** A period's classic due-total: while it is open, the dues (as shown on their rows now) of every person's claims that
51: *  count by their status now (see live) whose due-by falls in it, added up; once closed or soft-closed, the figure
52: *  fixed then (see personPeriodDueTotal). */
53:export function classicPeriodDueTotal(period: Period, claims: Claim[], people: Person[], rates: Rate[],
54:    floor: DatedValue, late: Late): string {
55:  if (period.closed || period.soft) return periodDueTotal(period, claims, people, rates, floor, late);
56:  return sumDue(people.flatMap((p) => live(claims.filter((c) => c.personId === p.id), [p], late.today)
57:    .filter((c) => periodOf([period], dueBy(c)))
58:    .map((c) => claimDue(c, rateOn(rates, gradeOn(p, c.date), c.date, c.id), floor, late))));
59:}

